public indirect enum Action: Codable, Sendable, Equatable {
    case ping
    case setName(String)
    case update(UpdatePayload)
    case multiTuple(ContractTuple2<UInt32, String>)
    case multiStruct(Action_MultiStruct)

    public init(from decoder: any Decoder) throws {
        if let name = try? decoder.singleValueContainer().decode(String.self) {
            switch name {
            case "Ping": self = .ping
            default: throw contractUnknownVariant("Action", name, decoder.codingPath)
            }
            return
        }
        let container = try decoder.container(keyedBy: ContractCodingKey.self)
        guard let key = container.allKeys.first else {
            throw contractUnknownVariant("Action", "", decoder.codingPath)
        }
        switch key.stringValue {
        case "SetName": self = .setName(try container.decode(String.self, forKey: key))
        case "Update": self = .update(try container.decode(UpdatePayload.self, forKey: key))
        case "MultiTuple": self = .multiTuple(try container.decode(ContractTuple2<UInt32, String>.self, forKey: key))
        case "MultiStruct": self = .multiStruct(try container.decode(Action_MultiStruct.self, forKey: key))
        default: throw contractUnknownVariant("Action", key.stringValue, decoder.codingPath)
        }
    }

    public func encode(to encoder: any Encoder) throws {
        switch self {
        case .ping:
            var container = encoder.singleValueContainer()
            try container.encode("Ping")
        case .setName(let value):
            var container = encoder.container(keyedBy: ContractCodingKey.self)
            try container.encode(value, forKey: ContractCodingKey("SetName"))
        case .update(let value):
            var container = encoder.container(keyedBy: ContractCodingKey.self)
            try container.encode(value, forKey: ContractCodingKey("Update"))
        case .multiTuple(let value):
            var container = encoder.container(keyedBy: ContractCodingKey.self)
            try container.encode(value, forKey: ContractCodingKey("MultiTuple"))
        case .multiStruct(let value):
            var container = encoder.container(keyedBy: ContractCodingKey.self)
            try container.encode(value, forKey: ContractCodingKey("MultiStruct"))
        }
    }
}

