    public init(bio: String? = nil, avatar: [UInt8]? = nil, nicknames: [String]) {
        self.bio = bio
        self.avatar = avatar
        self.nicknames = nicknames
    }
}

/// Custom enum in module
public indirect enum Status: Codable, Sendable, Equatable {
    /// Waiting to start.
    case pending
    case active(Status_Active)
    case completed(Status_Completed)

    public init(from decoder: any Decoder) throws {
        if let name = try? decoder.singleValueContainer().decode(String.self) {
            switch name {
            case "Pending": self = .pending
            default: throw contractUnknownVariant("Status", name, decoder.codingPath)
            }
            return
        }
        let container = try decoder.container(keyedBy: ContractCodingKey.self)
        guard let key = container.allKeys.first else {
            throw contractUnknownVariant("Status", "", decoder.codingPath)
        }
        switch key.stringValue {
        case "Active": self = .active(try container.decode(Status_Active.self, forKey: key))
        case "Completed": self = .completed(try container.decode(Status_Completed.self, forKey: key))
        default: throw contractUnknownVariant("Status", key.stringValue, decoder.codingPath)
        }
    }

    public func encode(to encoder: any Encoder) throws {
        switch self {
        case .pending:
            var container = encoder.singleValueContainer()
            try container.encode("Pending")
        case .active(let value):
            var container = encoder.container(keyedBy: ContractCodingKey.self)
            try container.encode(value, forKey: ContractCodingKey("Active"))
        case .completed(let value):
            var container = encoder.container(keyedBy: ContractCodingKey.self)
            try container.encode(value, forKey: ContractCodingKey("Completed"))
        }
    }
}

