public indirect enum WireOutcome: Codable, Sendable, Equatable {
    case done
    case failed(String)

    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: ContractCodingKey.self)
        let tag = try container.decode(String.self, forKey: ContractCodingKey("kind"))
        switch tag {
        case "Done": self = .done
        case "Failed": self = .failed(try container.decode(String.self, forKey: ContractCodingKey("data")))
        default: throw contractUnknownVariant("WireOutcome", tag, decoder.codingPath)
        }
    }

    public func encode(to encoder: any Encoder) throws {
        var container = encoder.container(keyedBy: ContractCodingKey.self)
        switch self {
        case .done:
            try container.encode("Done", forKey: ContractCodingKey("kind"))
        case .failed(let value):
            try container.encode("Failed", forKey: ContractCodingKey("kind"))
            try container.encode(value, forKey: ContractCodingKey("data"))
        }
    }
}

