public indirect enum WireStep: Codable, Sendable, Equatable {
    case retain(WireStep_Retain)
    case insert(WireStep_Insert)

    public init(from decoder: any Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let value = try? container.decode(WireStep_Retain.self) {
            self = .retain(value)
            return
        }
        if let value = try? container.decode(WireStep_Insert.self) {
            self = .insert(value)
            return
        }
        throw DecodingError.dataCorruptedError(in: container, debugDescription: "No WireStep variant matches")
    }

    public func encode(to encoder: any Encoder) throws {
        var container = encoder.singleValueContainer()
        switch self {
        case .retain(let value): try container.encode(value)
        case .insert(let value): try container.encode(value)
        }
    }
}

